<section class="panel"><div class="flex items-center justify-between"><div><h2 class="section-title">Rules</h2><p class="muted mt-1">First enabled match by priority wins.</p></div><button class="btn-secondary" type="button" @click="add()" :disabled="rules.length>=50">Add rule</button></div><div class="mt-4 space-y-4"><template x-for="(rule,i) in rules" :key="i"><article class="rounded-2xl border p-4"><div class="flex flex-wrap items-center justify-between gap-2"><h3 class="font-semibold" x-text="rule.name||'Rule'"></h3><div class="flex gap-1"><button class="btn-ghost" type="button" @click="move(i,-1)">Up</button><button class="btn-ghost" type="button" @click="move(i,1)">Down</button><button class="btn-ghost text-red-500" type="button" @click="rules.splice(i,1)">Remove</button></div></div><div class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label class="field-label">Name<input class="input mt-1" :name="`rules[${i}][name]`" x-model="rule.name" required maxlength="120"></label><label class="field-label">Priority<input class="input mt-1" type="number" :name="`rules[${i}][priority]`" x-model="rule.priority" required></label><label class="field-label">Match<select class="input mt-1" :name="`rules[${i}][match_type]`" x-model="rule.match_type"><option value="any">Any text</option><option value="exact">Exact text</option><option value="contains">Contains</option><option value="starts_with">Starts with</option><option value="condition">Contact condition</option></select></label><label class="field-label">Action<select class="input mt-1" :name="`rules[${i}][action_type]`" x-model="rule.action_type"><option value="reply_text">Reply with text</option><option value="reply_template">Reply with template</option><option value="handoff_to_human">Human handoff</option><option value="stop_bot">Stop bot</option></select></label></div><label class="field-label mt-3 block" x-show="['exact','contains','starts_with'].includes(rule.match_type)">Match text<input class="input mt-1" :name="`rules[${i}][match_value]`" x-model="rule.match_value" maxlength="500"></label><div class="mt-3 grid gap-3 sm:grid-cols-3" x-show="rule.match_type==='condition'"><select class="input" :name="`rules[${i}][condition_field]`" x-model="rule.condition_field"><option value="contact.company">Company</option><option value="contact.preferred_language">Preferred language</option><option value="contact.consent_status">Consent status</option><option value="contact.status">Contact status</option><option value="contact.opted_out">Opted out</option></select><select class="input" :name="`rules[${i}][condition_operator]`" x-model="rule.condition_operator"><option value="equals">Equals</option><option value="not_equals">Does not equal</option><option value="contains">Contains</option><option value="is_empty">Is empty</option><option value="is_not_empty">Is not empty</option><option value="is_true">Is true</option><option value="is_false">Is false</option></select><input class="input" :name="`rules[${i}][condition_value]`" x-model="rule.condition_value" placeholder="Value"></div><label class="field-label mt-3 block" x-show="rule.action_type==='reply_text'">Plain-text reply<textarea class="field mt-1 min-h-24" :name="`rules[${i}][reply_text]`" x-model="rule.reply_text" maxlength="4096"></textarea></label><label class="field-label mt-3 block" x-show="rule.action_type==='reply_template'">Published template<select class="input mt-1" :name="`rules[${i}][template_uuid]`" x-model="rule.template_uuid"><option value="">Select template</option>@foreach($templates as $template)<option value="{{ $template->uuid }}">{{ $template->name }}</option>@endforeach</select></label><div class="mt-3 flex flex-wrap gap-5"><label class="text-sm"><input type="checkbox" :name="`rules[${i}][is_enabled]`" value="1" x-model="rule.is_enabled"> Enabled</label><label class="text-sm"><input type="checkbox" :name="`rules[${i}][stop_processing]`" value="1" x-model="rule.stop_processing"> Stop processing</label></div></article></template></div></section>
